import { remote } from 'webdriverio';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const devFile = path.join(os.homedir(), '.qa-tester', 'devices.json');
const dev = fs.existsSync(devFile) ? JSON.parse(fs.readFileSync(devFile, 'utf8')) : {};
const env = (k, d) => process.env[k] || d;

export const PLATFORM = env('PLATFORM', 'android');
export const IS_IOS = PLATFORM === 'ios';
export const SHARE_BASE = 'https://find-workers-be-dev-200b59d90f39.herokuapp.com/share/user?id=';
export const USERS = {
  ios: { name: env('QA_IOS_USER_NAME', 'נקיה מורוזוב'), id: env('QA_IOS_USER_ID', '140') },
  android: { name: env('QA_ANDROID_USER_NAME', 'Alina Alina'), id: env('QA_ANDROID_USER_ID', '146') },
};
/** The other test account — the only one tests may interact with. */
export const PARTNER = IS_IOS ? USERS.android : USERS.ios;
export const APP_ID = IS_IOS ? 'com.juliusAgency.findWorkers' : 'com.yb.findworkers';

export async function startDriver() {
  const caps = IS_IOS ? {
    platformName: 'iOS', 'appium:automationName': 'XCUITest',
    'appium:udid': env('IOS_UDID', dev.ios?.udid), 'appium:bundleId': APP_ID,
    'appium:noReset': true, 'appium:forceAppLaunch': false, 'appium:usePrebuiltWDA': true,
    'appium:derivedDataPath': env('IOS_WDA_DERIVED', dev.ios?.derivedDataPath || path.join(os.homedir(), '.appium/wda-build')),
    'appium:updatedWDABundleId': env('IOS_WDA_BUNDLE', dev.ios?.wdaBundleId),
    'appium:xcodeOrgId': env('IOS_TEAM', dev.ios?.teamId), 'appium:xcodeSigningId': 'Apple Development',
    'appium:wdaLaunchTimeout': 240000, 'appium:newCommandTimeout': 600,
  } : {
    platformName: 'Android', 'appium:automationName': 'UiAutomator2',
    'appium:udid': env('ANDROID_UDID', dev.android?.udid), 'appium:appPackage': APP_ID,
    'appium:appActivity': 'com.yb.findworkers.MainActivity', 'appium:noReset': true,
    'appium:newCommandTimeout': 600,
  };
  const d = await remote({ hostname: '127.0.0.1', port: 4723, logLevel: 'warn', capabilities: caps });
  await d.activateApp(APP_ID);
  return d;
}

/** Element whose visible text / label equals (or contains) the given string. */
export function byText(d, text, contains = false) {
  if (IS_IOS) {
    const q = contains ? `label CONTAINS "${text}" OR name CONTAINS "${text}"` : `label == "${text}" OR name == "${text}"`;
    return d.$(`-ios predicate string:${q}`);
  }
  const x = contains ? `//*[contains(@text,"${text}") or contains(@content-desc,"${text}")]` : `//*[@text="${text}" or @content-desc="${text}"]`;
  return d.$(x);
}

export async function tapXY(d, x, y) {
  await d.action('pointer', { parameters: { pointerType: 'touch' } }).move({ x: Math.round(x), y: Math.round(y) }).down().pause(80).up().perform();
}

export async function tapElCenter(d, el) {
  const r = await el.getElementRect(el.elementId);
  await tapXY(d, r.x + r.width / 2, r.y + r.height / 2);
}

export const keyboardShown = (d) => d.isKeyboardShown();

/** Open a URL the way the OS does (camera / link tap) — app links / universal links. */
export async function openLink(d, url) {
  if (IS_IOS) await d.execute('mobile: deepLink', { url });
  else await d.execute('mobile: deepLink', { url, package: APP_ID });
}

export async function goTab(d, name) { await (await byText(d, name)).click(); }

/** Search from the home search screen. mode: 'עובדים' | 'עבודה'. */
export async function search(d, mode, query) {
  await goTab(d, 'חיפוש');
  const results = IS_IOS ? await d.$('~search-input-results') : null;
  if (results && await results.isExisting()) { await results.clearValue(); await d.pause(1500); }
  await (await byText(d, mode)).click();
  const input = IS_IOS ? await d.$('~search-input') : await d.$('android.widget.EditText');
  await input.click(); await input.setValue(query);
  if (IS_IOS) { await (await d.$('~search-input-submit')).click(); return; }
  // Android: the magnifier sits just left of the text field on the home screen
  const r = await input.getElementRect(input.elementId);
  await tapXY(d, r.x - 38, r.y + r.height / 2);
}

/** Backend the app talks to (same host the QA checks used 2026-10-26). */
export const API_BASE = env('QA_API_BASE', 'https://find-workers-be-dev-200b59d90f39.herokuapp.com');

/** Guest GET (no Authorization). Returns { status, headers, body }. */
export async function apiGet(p) {
  const r = await fetch(API_BASE + p);
  const text = await r.text();
  let body = null; try { body = JSON.parse(text); } catch { body = text; }
  return { status: r.status, headers: r.headers, body };
}
